      const p17ProjectionTriedRef = React.useRef(new Set())
      React.useEffect(() => {
        const services = P16_DIRECT_BRIDGE.services
        if (!services || !services.sessions || !services.sessions.list || typeof services.sessions.list.subscribe !== 'function') return undefined
        const dispose = services.sessions.list.subscribe(() => setP17Epoch((value) => value + 1))
        return typeof dispose === 'function' ? dispose : undefined
      }, [p16ServicesTick])
