        const isDefaultTarget = !targetState || (defaultStateId && targetState === defaultStateId)
        const nextIds = stillHasBinding || !isDefaultTarget ? currentIds.slice() : currentIds.filter((item) => item !== id)
        const changed = nextIds.length !== currentIds.length || nextBindings.length !== currentBindings.length
        if (!changed) return
        const ok = await wbPersistAssetBindings(nextIds, nextBindings)
