          const source = String(asset.source || '').trim()
          if (!source) continue
          const id = String(asset._cardId || asset.id || entry.cardId || entry.id || '').trim()
          const stateId = String(asset._stateId || entry.stateId || '').trim()
          const key = id + '\u0001' + stateId
          if (!id || seen.has(key)) continue
          seen.add(key)
          list.push({ id, stateId, name: String(asset.name || id), stateName: String(entry.stateName || asset._stateName || '默认') })
