          setWbVideoPreview({ shotIndex: wbShotIndex, shotNumber, prompt: String(shot.videoPrompt || '').trim(), ratio: videoParams.ratio === 'adaptive' ? wbVideoRatio() : videoParams.ratio, backend: 'libtv', videoParams, mode: videoParams.mode, referenceAssets: videoRefs.map((row) => ({ id: row.id, stateId: row.stateId, name: row.name })), estimate })
